const t = ($json.ticket || '').toLowerCase();
const high = ['production down','complete outage','security breach','data loss'].some(x => t.includes(x));
const p2 = ['401','504','multiple customers','degraded'].some(x => t.includes(x));
return [{ json: { ...$json, severity: high ? 'P1' : (p2 ? 'P2' : 'P3'), human_approval_required: high, route: high ? 'human_escalation_preview' : (p2 ? 'senior_support_review' : 'standard_support') } }];
